function hasDuplicate(nums) {
    const seen = new Set();
    for (const n of nums) {
        if (seen.has(n)) return true;
        seen.add(n);
    }
    return false;
}

function isAnagram(s, t) {
    if (s.length !== t.length) return false;
    const count = {};
    for (const c of s) count[c] = (count[c] || 0) + 1;
    for (const c of t) {
        if (!count[c]) return false;
        count[c]--;
    }
    return true;
}

function twoSum(nums, target) {
    const seen = new Map(); // value -> index
    for (let i = 0; i < nums.length; i++) {
        const diff = target - nums[i];
        if (seen.has(diff)) return [seen.get(diff), i];
        seen.set(nums[i], i);
    }
}

function groupAnagrams(strs) {
    const groups = new Map();
    for (const s of strs) {
        const count = new Array(26).fill(0);
        for (const c of s) count[c.charCodeAt(0) - 97]++;
        const key = count.join("#");
        if (!groups.has(key)) groups.set(key, []);
        groups.get(key).push(s);
    }
    return [...groups.values()];
}

function topKFrequent(nums, k) {
    const count = new Map();
    for (const n of nums) count.set(n, (count.get(n) || 0) + 1);

    const buckets = Array.from({ length: nums.length + 1 }, () => []);
    for (const [num, freq] of count) buckets[freq].push(num);

    const res = [];
    for (let freq = buckets.length - 1; freq > 0; freq--) {
        for (const num of buckets[freq]) {
            res.push(num);
            if (res.length === k) return res;
        }
    }
}

function encode(strs) {
    let res = "";
    for (const s of strs) res += s.length + "#" + s;
    return res;
}

function decode(str) {
    const res = [];
    let i = 0;
    while (i < str.length) {
        let j = i;
        while (str[j] !== "#") j++;
        const length = parseInt(str.slice(i, j));
        res.push(str.slice(j + 1, j + 1 + length));
        i = j + 1 + length;
    }
    return res;
}

function productExceptSelf(nums) {
    const n = nums.length;
    const res = new Array(n).fill(1);

    let prefix = 1;
    for (let i = 0; i < n; i++) {
        res[i] = prefix;
        prefix *= nums[i];
    }
    let postfix = 1;
    for (let i = n - 1; i >= 0; i--) {
        res[i] *= postfix;
        postfix *= nums[i];
    }
    return res;
}

function longestConsecutive(nums) {
    const numSet = new Set(nums);
    let longest = 0;
    for (const n of numSet) {
        if (!numSet.has(n - 1)) {          // only start at a sequence head
            let length = 1;
            while (numSet.has(n + length)) length++;
            longest = Math.max(longest, length);
        }
    }
    return longest;
}

function isPalindrome(s) {
    const isAlnum = (c) => /[a-z0-9]/i.test(c);
    let l = 0, r = s.length - 1;
    while (l < r) {
        while (l < r && !isAlnum(s[l])) l++;
        while (l < r && !isAlnum(s[r])) r--;
        if (s[l].toLowerCase() !== s[r].toLowerCase()) return false;
        l++;
        r--;
    }
    return true;
}

function threeSum(nums) {
    nums.sort((a, b) => a - b);
    const res = [];
    for (let i = 0; i < nums.length; i++) {
        if (i > 0 && nums[i] === nums[i - 1]) continue;   // skip dup anchor
        let l = i + 1, r = nums.length - 1;
        while (l < r) {
            const sum = nums[i] + nums[l] + nums[r];
            if (sum > 0) r--;
            else if (sum < 0) l++;
            else {
                res.push([nums[i], nums[l], nums[r]]);
                l++;
                r--;
                while (l < r && nums[l] === nums[l - 1]) l++;  // skip dup
            }
        }
    }
    return res;
}

function maxArea(heights) {
    let l = 0, r = heights.length - 1;
    let res = 0;
    while (l < r) {
        const area = (r - l) * Math.min(heights[l], heights[r]);
        res = Math.max(res, area);
        if (heights[l] < heights[r]) l++;
        else r--;
    }
    return res;
}

function maxProfit(prices) {
    let minPrice = prices[0];
    let profit = 0;
    for (let i = 1; i < prices.length; i++) {
        minPrice = Math.min(minPrice, prices[i]);
        profit = Math.max(profit, prices[i] - minPrice);
    }
    return profit;
}

function lengthOfLongestSubstring(s) {
    const seen = new Set();
    let l = 0, res = 0;
    for (let r = 0; r < s.length; r++) {
        while (seen.has(s[r])) {
            seen.delete(s[l]);
            l++;
        }
        seen.add(s[r]);
        res = Math.max(res, r - l + 1);
    }
    return res;
}

function characterReplacement(s, k) {
    const count = {};
    let res = 0, l = 0, maxf = 0;
    for (let r = 0; r < s.length; r++) {
        count[s[r]] = (count[s[r]] || 0) + 1;
        maxf = Math.max(maxf, count[s[r]]);
        while ((r - l + 1) - maxf > k) {
            count[s[l]]--;
            l++;
        }
        res = Math.max(res, r - l + 1);
    }
    return res;
}

function minWindow(s, t) {
    if (t === "") return "";
    const countT = {};
    for (const c of t) countT[c] = (countT[c] || 0) + 1;

    const need = Object.keys(countT).length;
    const window = {};
    let have = 0;
    let res = [-1, -1], resLen = Infinity;
    let l = 0;
    for (let r = 0; r < s.length; r++) {
        const c = s[r];
        window[c] = (window[c] || 0) + 1;
        if (c in countT && window[c] === countT[c]) have++;
        while (have === need) {
            if (r - l + 1 < resLen) {
                res = [l, r];
                resLen = r - l + 1;
            }
            window[s[l]]--;
            if (s[l] in countT && window[s[l]] < countT[s[l]]) have--;
            l++;
        }
    }
    const [start, end] = res;
    return resLen === Infinity ? "" : s.slice(start, end + 1);
}

function isValid(s) {
    const stack = [];
    const closeToOpen = { ")": "(", "]": "[", "}": "{" };
    for (const c of s) {
        if (c in closeToOpen) {
            if (stack.length && stack[stack.length - 1] === closeToOpen[c]) {
                stack.pop();
            } else {
                return false;
            }
        } else {
            stack.push(c);
        }
    }
    return stack.length === 0;
}

function findMin(nums) {
    let l = 0, r = nums.length - 1;
    let res = nums[0];
    while (l <= r) {
        if (nums[l] <= nums[r]) {            // this slice is already sorted
            res = Math.min(res, nums[l]);
            break;
        }
        const m = Math.floor((l + r) / 2);
        res = Math.min(res, nums[m]);
        if (nums[m] >= nums[l]) l = m + 1;   // left half sorted → min is right
        else r = m - 1;                      // min is in the left half
    }
    return res;
}

function search(nums, target) {
    let l = 0, r = nums.length - 1;
    while (l <= r) {
        const m = Math.floor((l + r) / 2);
        if (nums[m] === target) return m;
        if (nums[l] <= nums[m]) {            // left half sorted
            if (target > nums[m] || target < nums[l]) l = m + 1;
            else r = m - 1;
        } else {                             // right half sorted
            if (target < nums[m] || target > nums[r]) r = m - 1;
            else l = m + 1;
        }
    }
    return -1;
}

// function ListNode(val, next) { this.val = val; this.next = next ?? null; }
function reverseList(head) {
    let prev = null;
    let curr = head;
    while (curr) {
        const next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

function mergeTwoLists(l1, l2) {
    const dummy = new ListNode();
    let tail = dummy;
    while (l1 && l2) {
        if (l1.val < l2.val) {
            tail.next = l1;
            l1 = l1.next;
        } else {
            tail.next = l2;
            l2 = l2.next;
        }
        tail = tail.next;
    }
    tail.next = l1 || l2;                 // attach the remainder
    return dummy.next;
}

function hasCycle(head) {
    let slow = head, fast = head;
    while (fast && fast.next) {
        slow = slow.next;
        fast = fast.next.next;
        if (slow === fast) return true;
    }
    return false;
}

function reorderList(head) {
    // 1) find middle
    let slow = head, fast = head.next;
    while (fast && fast.next) {
        slow = slow.next;
        fast = fast.next.next;
    }

    // 2) reverse second half
    let second = slow.next;
    slow.next = null;
    let prev = null;
    while (second) {
        const next = second.next;
        second.next = prev;
        prev = second;
        second = next;
    }

    // 3) merge the two halves
    let first = head;
    second = prev;
    while (second) {
        const t1 = first.next, t2 = second.next;
        first.next = second;
        second.next = t1;
        first = t1;
        second = t2;
    }
}

function removeNthFromEnd(head, n) {
    const dummy = new ListNode(0, head);
    let left = dummy;
    let right = head;
    while (n > 0) {                       // open a gap of n nodes
        right = right.next;
        n--;
    }
    while (right) {                       // advance both until right falls off
        left = left.next;
        right = right.next;
    }
    left.next = left.next.next;           // skip the target
    return dummy.next;
}

function mergeKLists(lists) {
    if (!lists || lists.length === 0) return null;
    while (lists.length > 1) {
        const merged = [];
        for (let i = 0; i < lists.length; i += 2) {
            const l1 = lists[i];
            const l2 = i + 1 < lists.length ? lists[i + 1] : null;
            merged.push(mergeTwoLists(l1, l2));
        }
        lists = merged;
    }
    return lists[0];
}

function mergeTwoLists(l1, l2) {
    const dummy = new ListNode();
    let tail = dummy;
    while (l1 && l2) {
        if (l1.val < l2.val) { tail.next = l1; l1 = l1.next; }
        else { tail.next = l2; l2 = l2.next; }
        tail = tail.next;
    }
    tail.next = l1 || l2;
    return dummy.next;
}

// TreeNode: { val, left, right }
function invertTree(root) {
    if (!root) return null;
    [root.left, root.right] = [invertTree(root.right), invertTree(root.left)];
    return root;
}

function maxDepth(root) {
    if (!root) return 0;
    return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));
}

function isSameTree(p, q) {
    if (!p && !q) return true;
    if (!p || !q || p.val !== q.val) return false;
    return isSameTree(p.left, q.left) && isSameTree(p.right, q.right);
}

function isSubtree(root, subRoot) {
    if (!subRoot) return true;
    if (!root) return false;
    if (isSameTree(root, subRoot)) return true;
    return isSubtree(root.left, subRoot) || isSubtree(root.right, subRoot);
}

function isSameTree(p, q) {
    if (!p && !q) return true;
    if (!p || !q || p.val !== q.val) return false;
    return isSameTree(p.left, q.left) && isSameTree(p.right, q.right);
}

function lowestCommonAncestor(root, p, q) {
    let cur = root;
    while (cur) {
        if (p.val > cur.val && q.val > cur.val) cur = cur.right;
        else if (p.val < cur.val && q.val < cur.val) cur = cur.left;
        else return cur;                 // split point = LCA
    }
}

function levelOrder(root) {
    const res = [];
    if (!root) return res;
    let queue = [root];
    while (queue.length) {
        const level = [], next = [];
        for (const node of queue) {
            level.push(node.val);
            if (node.left) next.push(node.left);
            if (node.right) next.push(node.right);
        }
        res.push(level);
        queue = next;
    }
    return res;
}

function isValidBST(root) {
    function valid(node, left, right) {
        if (!node) return true;
        if (!(left < node.val && node.val < right)) return false;
        return valid(node.left, left, node.val) &&
               valid(node.right, node.val, right);
    }
    return valid(root, -Infinity, Infinity);
}

function kthSmallest(root, k) {
    const stack = [];
    let cur = root;
    while (cur || stack.length) {
        while (cur) { stack.push(cur); cur = cur.left; }
        cur = stack.pop();
        if (--k === 0) return cur.val;
        cur = cur.right;
    }
}

function buildTree(preorder, inorder) {
    const idx = new Map();
    inorder.forEach((v, i) => idx.set(v, i));
    let pre = 0;
    function build(left, right) {
        if (left > right) return null;
        const root = new TreeNode(preorder[pre++]);
        const mid = idx.get(root.val);
        root.left = build(left, mid - 1);
        root.right = build(mid + 1, right);
        return root;
    }
    return build(0, inorder.length - 1);
}

function maxPathSum(root) {
    let res = -Infinity;
    function dfs(node) {
        if (!node) return 0;
        const left = Math.max(dfs(node.left), 0);   // drop negatives
        const right = Math.max(dfs(node.right), 0);
        res = Math.max(res, node.val + left + right); // split at node
        return node.val + Math.max(left, right);      // extend upward
    }
    dfs(root);
    return res;
}

function serialize(root) {
    const res = [];
    (function dfs(node) {
        if (!node) { res.push("N"); return; }
        res.push(String(node.val));
        dfs(node.left);
        dfs(node.right);
    })(root);
    return res.join(",");
}

function deserialize(data) {
    const vals = data.split(",");
    let i = 0;
    function dfs() {
        if (vals[i] === "N") { i++; return null; }
        const node = new TreeNode(Number(vals[i++]));
        node.left = dfs();
        node.right = dfs();
        return node;
    }
    return dfs();
}

class Heap {                     // generic binary heap
    constructor(cmp) { this.a = []; this.cmp = cmp; }
    size() { return this.a.length; }
    peek() { return this.a[0]; }
    push(v) {
        const a = this.a; a.push(v);
        let i = a.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (this.cmp(a[i], a[p]) >= 0) break;
            [a[i], a[p]] = [a[p], a[i]]; i = p;
        }
    }
    pop() {
        const a = this.a, top = a[0], last = a.pop();
        if (a.length) {
            a[0] = last;
            let i = 0;
            while (true) {
                let s = i, l = 2*i+1, r = 2*i+2;
                if (l < a.length && this.cmp(a[l], a[s]) < 0) s = l;
                if (r < a.length && this.cmp(a[r], a[s]) < 0) s = r;
                if (s === i) break;
                [a[i], a[s]] = [a[s], a[i]]; i = s;
            }
        }
        return top;
    }
}

class MedianFinder {
    constructor() {
        this.small = new Heap((a, b) => b - a); // max-heap (low half)
        this.large = new Heap((a, b) => a - b); // min-heap (high half)
    }
    addNum(num) {
        this.small.push(num);
        if (this.small.size() && this.large.size() &&
            this.small.peek() > this.large.peek())
            this.large.push(this.small.pop());
        if (this.small.size() > this.large.size() + 1) this.large.push(this.small.pop());
        if (this.large.size() > this.small.size() + 1) this.small.push(this.large.pop());
    }
    findMedian() {
        if (this.small.size() > this.large.size()) return this.small.peek();
        if (this.large.size() > this.small.size()) return this.large.peek();
        return (this.small.peek() + this.large.peek()) / 2;
    }
}

function combinationSum(candidates, target) {
    const res = [], cur = [];
    function dfs(i, total) {
        if (total === target) { res.push([...cur]); return; }
        if (i >= candidates.length || total > target) return;
        cur.push(candidates[i]);          // choose i (can reuse)
        dfs(i, total + candidates[i]);
        cur.pop();                        // un-choose
        dfs(i + 1, total);                // skip i
    }
    dfs(0, 0);
    return res;
}

function exist(board, word) {
    const rows = board.length, cols = board[0].length;
    function dfs(r, c, i) {
        if (i === word.length) return true;
        if (r < 0 || c < 0 || r >= rows || c >= cols || board[r][c] !== word[i])
            return false;
        const tmp = board[r][c];
        board[r][c] = "#";                // mark visited
        const found = dfs(r+1, c, i+1) || dfs(r-1, c, i+1) ||
                      dfs(r, c+1, i+1) || dfs(r, c-1, i+1);
        board[r][c] = tmp;                // restore
        return found;
    }
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++)
            if (dfs(r, c, 0)) return true;
    return false;
}

class TrieNode {
    constructor() { this.children = {}; this.end = false; }
}

class Trie {
    constructor() { this.root = new TrieNode(); }
    insert(word) {
        let cur = this.root;
        for (const c of word) {
            if (!cur.children[c]) cur.children[c] = new TrieNode();
            cur = cur.children[c];
        }
        cur.end = true;
    }
    search(word)     { const n = this._find(word);   return !!n && n.end; }
    startsWith(pre)  { return !!this._find(pre); }
    _find(str) {
        let cur = this.root;
        for (const c of str) {
            if (!cur.children[c]) return null;
            cur = cur.children[c];
        }
        return cur;
    }
}

class WordDictionary {
    constructor() { this.root = { children: {}, end: false }; }
    addWord(word) {
        let cur = this.root;
        for (const c of word) {
            if (!cur.children[c]) cur.children[c] = { children: {}, end: false };
            cur = cur.children[c];
        }
        cur.end = true;
    }
    search(word) {
        const dfs = (j, node) => {
            let cur = node;
            for (let i = j; i < word.length; i++) {
                const c = word[i];
                if (c === ".") {
                    return Object.values(cur.children)
                        .some(child => dfs(i + 1, child));
                }
                if (!cur.children[c]) return false;
                cur = cur.children[c];
            }
            return cur.end;
        };
        return dfs(0, this.root);
    }
}

class TrieNode { constructor() { this.children = {}; this.word = null; } }

function findWords(board, words) {
    const root = new TrieNode();
    for (const w of words) {
        let cur = root;
        for (const c of w) {
            if (!cur.children[c]) cur.children[c] = new TrieNode();
            cur = cur.children[c];
        }
        cur.word = w;
    }
    const rows = board.length, cols = board[0].length, res = [];
    function dfs(r, c, node) {
        if (r < 0 || c < 0 || r >= rows || c >= cols) return;
        const ch = board[r][c];
        const next = node.children[ch];
        if (!next) return;
        if (next.word) { res.push(next.word); next.word = null; } // dedupe
        board[r][c] = "#";
        dfs(r+1,c,next); dfs(r-1,c,next); dfs(r,c+1,next); dfs(r,c-1,next);
        board[r][c] = ch;
    }
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++)
            dfs(r, c, root);
    return res;
}

function numIslands(grid) {
    if (!grid.length) return 0;
    const rows = grid.length, cols = grid[0].length;
    let count = 0;
    function dfs(r, c) {
        if (r < 0 || c < 0 || r >= rows || c >= cols || grid[r][c] !== "1") return;
        grid[r][c] = "0";                 // sink so we don't revisit
        dfs(r+1,c); dfs(r-1,c); dfs(r,c+1); dfs(r,c-1);
    }
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++)
            if (grid[r][c] === "1") { count++; dfs(r, c); }
    return count;
}

// Node: { val, neighbors: [] }
function cloneGraph(node) {
    const clones = new Map();             // original -> copy
    function dfs(n) {
        if (!n) return null;
        if (clones.has(n)) return clones.get(n);
        const copy = new Node(n.val);
        clones.set(n, copy);
        for (const nei of n.neighbors) copy.neighbors.push(dfs(nei));
        return copy;
    }
    return dfs(node);
}

function pacificAtlantic(heights) {
    const rows = heights.length, cols = heights[0].length;
    const pac = Array.from({length: rows}, () => Array(cols).fill(false));
    const atl = Array.from({length: rows}, () => Array(cols).fill(false));
    function dfs(r, c, seen, prev) {
        if (r < 0 || c < 0 || r >= rows || c >= cols ||
            seen[r][c] || heights[r][c] < prev) return;
        seen[r][c] = true;
        dfs(r+1,c,seen,heights[r][c]); dfs(r-1,c,seen,heights[r][c]);
        dfs(r,c+1,seen,heights[r][c]); dfs(r,c-1,seen,heights[r][c]);
    }
    for (let c = 0; c < cols; c++) {
        dfs(0, c, pac, heights[0][c]);
        dfs(rows-1, c, atl, heights[rows-1][c]);
    }
    for (let r = 0; r < rows; r++) {
        dfs(r, 0, pac, heights[r][0]);
        dfs(r, cols-1, atl, heights[r][cols-1]);
    }
    const res = [];
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++)
            if (pac[r][c] && atl[r][c]) res.push([r, c]);
    return res;
}

function canFinish(numCourses, prerequisites) {
    const adj = Array.from({length: numCourses}, () => []);
    for (const [crs, pre] of prerequisites) adj[crs].push(pre);
    const state = new Array(numCourses).fill(0); // 0 new,1 visiting,2 done
    function dfs(c) {
        if (state[c] === 1) return false;         // back-edge = cycle
        if (state[c] === 2) return true;
        state[c] = 1;
        for (const pre of adj[c]) if (!dfs(pre)) return false;
        state[c] = 2;
        return true;
    }
    for (let c = 0; c < numCourses; c++) if (!dfs(c)) return false;
    return true;
}

function validTree(n, edges) {
    if (edges.length !== n - 1) return false;   // a tree has exactly n-1 edges
    const adj = Array.from({length: n}, () => []);
    for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
    const visited = new Set();
    function dfs(node, parent) {
        if (visited.has(node)) return false;     // cycle
        visited.add(node);
        for (const nei of adj[node]) {
            if (nei === parent) continue;
            if (!dfs(nei, node)) return false;
        }
        return true;
    }
    return dfs(0, -1) && visited.size === n;      // acyclic AND connected
}

function countComponents(n, edges) {
    const parent = Array.from({length: n}, (_, i) => i);
    const rank = new Array(n).fill(1);
    function find(x) {
        while (x !== parent[x]) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    function union(a, b) {
        const ra = find(a), rb = find(b);
        if (ra === rb) return 0;
        if (rank[ra] < rank[rb]) { parent[ra] = rb; rank[rb] += rank[ra]; }
        else { parent[rb] = ra; rank[ra] += rank[rb]; }
        return 1;
    }
    let count = n;
    for (const [a, b] of edges) count -= union(a, b);
    return count;
}

function alienOrder(words) {
    const adj = new Map();
    for (const w of words) for (const c of w) if (!adj.has(c)) adj.set(c, new Set());
    for (let i = 0; i < words.length - 1; i++) {
        const w1 = words[i], w2 = words[i + 1];
        const minLen = Math.min(w1.length, w2.length);
        if (w1.length > w2.length && w1.slice(0, minLen) === w2.slice(0, minLen))
            return "";                    // invalid: prefix follows longer word
        for (let j = 0; j < minLen; j++)
            if (w1[j] !== w2[j]) { adj.get(w1[j]).add(w2[j]); break; }
    }
    const visited = new Map();            // char -> true(on path)/false(done)
    const res = [];
    function dfs(c) {
        if (visited.has(c)) return visited.get(c);  // true = cycle
        visited.set(c, true);
        for (const nei of adj.get(c)) if (dfs(nei)) return true;
        visited.set(c, false);
        res.push(c);
        return false;
    }
    for (const c of adj.keys()) if (dfs(c)) return "";
    return res.reverse().join("");
}

function climbStairs(n) {
    let a = 1, b = 1;
    for (let i = 0; i < n - 1; i++) [a, b] = [b, a + b];
    return b;
}

function rob(nums) {
    let prev = 0, curr = 0;
    for (const n of nums)
        [prev, curr] = [curr, Math.max(curr, prev + n)];
    return curr;
}

function rob(nums) {
    if (nums.length === 1) return nums[0];
    const line = (arr) => {
        let prev = 0, curr = 0;
        for (const n of arr) [prev, curr] = [curr, Math.max(curr, prev + n)];
        return curr;
    };
    return Math.max(line(nums.slice(1)), line(nums.slice(0, -1)));
}

function longestPalindrome(s) {
    let res = "";
    const expand = (l, r) => {
        while (l >= 0 && r < s.length && s[l] === s[r]) { l--; r++; }
        return s.slice(l + 1, r);
    };
    for (let i = 0; i < s.length; i++) {
        const odd = expand(i, i);         // odd-length center
        const even = expand(i, i + 1);    // even-length center
        if (odd.length > res.length) res = odd;
        if (even.length > res.length) res = even;
    }
    return res;
}

function countSubstrings(s) {
    let count = 0;
    const expand = (l, r) => {
        while (l >= 0 && r < s.length && s[l] === s[r]) { count++; l--; r++; }
    };
    for (let i = 0; i < s.length; i++) {
        expand(i, i);
        expand(i, i + 1);
    }
    return count;
}

function numDecodings(s) {
    const dp = new Map([[s.length, 1]]);
    function dfs(i) {
        if (dp.has(i)) return dp.get(i);
        if (s[i] === "0") return 0;                  // no leading zero
        let res = dfs(i + 1);                         // take one digit
        if (i + 1 < s.length &&
            (s[i] === "1" || (s[i] === "2" && s[i + 1] <= "6")))
            res += dfs(i + 2);                        // take two digits (10–26)
        dp.set(i, res);
        return res;
    }
    return dfs(0);
}

function coinChange(coins, amount) {
    const dp = new Array(amount + 1).fill(amount + 1); // amount+1 = "infinity"
    dp[0] = 0;
    for (let a = 1; a <= amount; a++)
        for (const c of coins)
            if (a - c >= 0) dp[a] = Math.min(dp[a], 1 + dp[a - c]);
    return dp[amount] === amount + 1 ? -1 : dp[amount];
}

function maxProduct(nums) {
    let res = Math.max(...nums);
    let curMin = 1, curMax = 1;
    for (const n of nums) {
        const tmp = curMax * n;
        curMax = Math.max(n, tmp, curMin * n);
        curMin = Math.min(n, tmp, curMin * n);
        res = Math.max(res, curMax);
    }
    return res;
}

function wordBreak(s, wordDict) {
    const words = new Set(wordDict);
    const dp = new Array(s.length + 1).fill(false);
    dp[s.length] = true;                              // empty suffix is valid
    for (let i = s.length - 1; i >= 0; i--)
        for (let j = i + 1; j <= s.length; j++)
            if (dp[j] && words.has(s.slice(i, j))) { dp[i] = true; break; }
    return dp[0];
}

function lengthOfLIS(nums) {
    const dp = new Array(nums.length).fill(1);
    for (let i = nums.length - 1; i >= 0; i--)
        for (let j = i + 1; j < nums.length; j++)
            if (nums[i] < nums[j]) dp[i] = Math.max(dp[i], 1 + dp[j]);
    return Math.max(...dp);
}

function uniquePaths(m, n) {
    let row = new Array(n).fill(1);       // bottom row: 1 path each
    for (let i = 1; i < m; i++)
        for (let j = 1; j < n; j++)
            row[j] += row[j - 1];         // from above + from left
    return row[n - 1];
}

function longestCommonSubsequence(text1, text2) {
    const m = text1.length, n = text2.length;
    const dp = Array.from({length: m + 1}, () => new Array(n + 1).fill(0));
    for (let i = m - 1; i >= 0; i--)
        for (let j = n - 1; j >= 0; j--)
            dp[i][j] = text1[i] === text2[j]
                ? 1 + dp[i + 1][j + 1]
                : Math.max(dp[i + 1][j], dp[i][j + 1]);
    return dp[0][0];
}

function maxSubArray(nums) {
    let maxSum = nums[0], cur = 0;
    for (const n of nums) {
        cur = Math.max(n, cur + n);       // drop the prefix if it hurts
        maxSum = Math.max(maxSum, cur);
    }
    return maxSum;
}

function canJump(nums) {
    let goal = nums.length - 1;
    for (let i = nums.length - 1; i >= 0; i--)
        if (i + nums[i] >= goal) goal = i; // i can reach the current goal
    return goal === 0;
}

function insert(intervals, newInterval) {
    const res = [];
    let i = 0;
    const n = intervals.length;
    while (i < n && intervals[i][1] < newInterval[0]) res.push(intervals[i++]);
    while (i < n && intervals[i][0] <= newInterval[1]) {   // overlaps → merge
        newInterval[0] = Math.min(newInterval[0], intervals[i][0]);
        newInterval[1] = Math.max(newInterval[1], intervals[i][1]);
        i++;
    }
    res.push(newInterval);
    while (i < n) res.push(intervals[i++]);
    return res;
}

function merge(intervals) {
    intervals.sort((a, b) => a[0] - b[0]);
    const res = [intervals[0]];
    for (const [start, end] of intervals.slice(1)) {
        const last = res[res.length - 1];
        if (start <= last[1]) last[1] = Math.max(last[1], end); // overlap
        else res.push([start, end]);
    }
    return res;
}

function eraseOverlapIntervals(intervals) {
    intervals.sort((a, b) => a[0] - b[0]);
    let res = 0, prevEnd = intervals[0][1];
    for (let i = 1; i < intervals.length; i++) {
        const [start, end] = intervals[i];
        if (start >= prevEnd) prevEnd = end;              // keep, no overlap
        else { res++; prevEnd = Math.min(prevEnd, end); } // remove the one ending later
    }
    return res;
}

function canAttendMeetings(intervals) {
    intervals.sort((a, b) => a[0] - b[0]);
    for (let i = 1; i < intervals.length; i++)
        if (intervals[i][0] < intervals[i - 1][1]) return false; // overlap
    return true;
}

function minMeetingRooms(intervals) {
    const starts = intervals.map(i => i[0]).sort((a, b) => a - b);
    const ends   = intervals.map(i => i[1]).sort((a, b) => a - b);
    let rooms = 0, maxRooms = 0, s = 0, e = 0;
    while (s < starts.length) {
        if (starts[s] < ends[e]) { rooms++; s++; }   // a meeting starts
        else { rooms--; e++; }                        // one frees a room
        maxRooms = Math.max(maxRooms, rooms);
    }
    return maxRooms;
}

function rotate(matrix) {
    const n = matrix.length;
    for (let i = 0; i < n; i++)                    // transpose
        for (let j = i + 1; j < n; j++)
            [matrix[i][j], matrix[j][i]] = [matrix[j][i], matrix[i][j]];
    for (let i = 0; i < n; i++) matrix[i].reverse(); // reverse each row
}

function spiralOrder(matrix) {
    const res = [];
    let top = 0, bottom = matrix.length, left = 0, right = matrix[0].length;
    while (top < bottom && left < right) {
        for (let j = left; j < right; j++) res.push(matrix[top][j]);
        top++;
        for (let i = top; i < bottom; i++) res.push(matrix[i][right - 1]);
        right--;
        if (!(top < bottom && left < right)) break;
        for (let j = right - 1; j >= left; j--) res.push(matrix[bottom - 1][j]);
        bottom--;
        for (let i = bottom - 1; i >= top; i--) res.push(matrix[i][left]);
        left++;
    }
    return res;
}

function setZeroes(matrix) {
    const rows = matrix.length, cols = matrix[0].length;
    let firstRowZero = false;
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++)
            if (matrix[r][c] === 0) {
                matrix[0][c] = 0;
                if (r > 0) matrix[r][0] = 0;
                else firstRowZero = true;
            }
    for (let r = 1; r < rows; r++)
        for (let c = 1; c < cols; c++)
            if (matrix[0][c] === 0 || matrix[r][0] === 0) matrix[r][c] = 0;
    if (matrix[0][0] === 0) for (let r = 0; r < rows; r++) matrix[r][0] = 0;
    if (firstRowZero)       for (let c = 0; c < cols; c++) matrix[0][c] = 0;
}

function hammingWeight(n) {
    let count = 0;
    while (n !== 0) {
        n &= (n - 1);          // clears the lowest set bit
        count++;
    }
    return count;
}

function countBits(n) {
    const dp = new Array(n + 1).fill(0);
    for (let i = 1; i <= n; i++)
        dp[i] = dp[i >> 1] + (i & 1);   // bits(i) = bits(i/2) + last bit
    return dp;
}

function reverseBits(n) {
    let res = 0;
    for (let i = 0; i < 32; i++) {
        res = (res << 1) | (n & 1);   // shift result, append n's last bit
        n >>>= 1;                     // unsigned shift
    }
    return res >>> 0;                 // interpret as unsigned 32-bit
}

function missingNumber(nums) {
    let res = nums.length;
    for (let i = 0; i < nums.length; i++)
        res ^= i ^ nums[i];        // pair up indices and values
    return res;
}

function getSum(a, b) {
    while (b !== 0) {
        const carry = (a & b) << 1;   // where both bits are 1
        a = a ^ b;                    // sum without carry
        b = carry;                    // add the carry next round
    }
    return a;
}
